import{_ as r,o as a,c as o,a2 as n}from"./chunks/framework.Dkj3JE0_.js";const u=JSON.parse('{"title":"日语基础语法","description":"","frontmatter":{"title":"日语基础语法"},"headers":[],"relativePath":"zh/blogs/JLPT-N2/grammars.md","filePath":"zh/blogs/JLPT-N2/grammars.md"}'),l={name:"zh/blogs/JLPT-N2/grammars.md"};function s(d,t,e,i,h,g){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="日语基础语法" tabindex="-1">日语基础语法 <a class="header-anchor" href="#日语基础语法" aria-label="Permalink to &quot;日语基础语法&quot;">​</a></h1><p>学习 N2 语法前，可以先复习这些基础句型。下文用 <strong>N</strong> 表示名词，<strong>A/B</strong> 表示句子中相应位置的词语。</p><h2 id="a-は-b-です" tabindex="-1">A は B です <a class="header-anchor" href="#a-は-b-です" aria-label="Permalink to &quot;A は B です&quot;">​</a></h2><p><strong>规则：</strong> は读作 <em>wa</em>，标记话题，相当于“说到 A”。です使名词或な形容词作谓语的句子更礼貌。话题不一定等于语法上的主语。</p><ul><li>私は留学生です。——我是留学生。</li><li>あの方は先生です。——那位是老师。</li></ul><p><strong>否定：</strong> A は B ではありません；口语中也可说 B じゃありません。</p><ul><li>私は先生ではありません。——我不是老师。</li></ul><p><strong>疑问：</strong> 在礼貌句末加 か；书面语中问号可以省略。</p><ul><li>あの方は先生ですか。——那位是老师吗？</li></ul><p><strong>连接谓语：</strong> B で可连接名词或な形容词谓语与后面的谓语。这里的 で 是判断词的连接形式，不是表示动作地点的助词。</p><ul><li>田中さんは先生で、作家です。——田中既是老师，也是作家。</li></ul><h2 id="指示词" tabindex="-1">指示词 <a class="header-anchor" href="#指示词" aria-label="Permalink to &quot;指示词&quot;">​</a></h2><p><strong>规则：</strong> 词首的 <strong>こ</strong> 指靠近说话人，<strong>そ</strong> 指靠近听话人或前文提到的事物，<strong>あ</strong> 指离双方都远，<strong>ど</strong> 用于提问。在对话中，そ、あ 也能指双方熟悉或记忆中的事物；空间距离只是基本用法。</p><table tabindex="0"><thead><tr><th>位置</th><th>事物</th><th>地点</th><th>方向／礼貌地指人</th></tr></thead><tbody><tr><td>靠近说话人</td><td>これ</td><td>ここ</td><td>こちら</td></tr><tr><td>靠近听话人</td><td>それ</td><td>そこ</td><td>そちら</td></tr><tr><td>离双方都远</td><td>あれ</td><td>あそこ</td><td>あちら</td></tr><tr><td>提问</td><td>どれ</td><td>どこ</td><td>どちら</td></tr></tbody></table><ul><li>これは私の本です。——这是我的书。</li><li>駅はどちらですか。——车站在哪个方向？（礼貌说法）</li></ul><p>こちら／そちら／あちら／どちら根据语境也可礼貌地指人或选项。</p><h2 id="n1-に-n2-が-あります-います" tabindex="-1">N1 に N2 が あります／います <a class="header-anchor" href="#n1-に-n2-が-あります-います" aria-label="Permalink to &quot;N1 に N2 が あります／います&quot;">​</a></h2><p><strong>规则：</strong> 这个句型说明 N1 这个地点有 N2。に标记地点，が标记存在的人或物。物品和植物用 <strong>あります</strong>；人和动物用 <strong>います</strong>。</p><ul><li>机の上に本があります。——桌上有一本书。</li><li>教室に学生がいます。——教室里有学生。</li></ul><p>表示拥有时，也可以把人作为存在的“地点”：私には兄がいます。——我有一个哥哥（字面上是“对我而言，有哥哥”）。</p><h2 id="n1-には-n2-が-あります-います" tabindex="-1">N1 には N2 が あります／います <a class="header-anchor" href="#n1-には-n2-が-あります-います" aria-label="Permalink to &quot;N1 には N2 が あります／います&quot;">​</a></h2><p><strong>规则：</strong> には由地点助词 に 和话题／对比助词 は 组成。它把 N1 作为陈述范围，有时暗示与其他地点或人作对比。根据 N2 选择 あります／います。</p><ul><li>この町には大きな公園があります。——这座城市有一座大公园。</li><li>私のクラスには留学生がいます。——我们班有留学生。</li></ul><p>比较 <strong>教室に学生がいます</strong>（“教室里有学生”）与 <strong>教室には学生がいます</strong>（“教室里倒是有学生”）：后者更突出“教室”这个范围。</p><h2 id="n1-は-n2-に-あります-います" tabindex="-1">N1 は N2 に あります／います <a class="header-anchor" href="#n1-は-n2-に-あります-います" aria-label="Permalink to &quot;N1 は N2 に あります／います&quot;">​</a></h2><p><strong>规则：</strong> 已经知道 N1，想说明它<strong>在哪里</strong>时，用这个语序。は标记已知话题，に标记所在地点。根据 N1 选择 あります／います。</p><ul><li>本は机の上にあります。——那本书在桌上。</li><li>先生は職員室にいます。——老师在办公室。</li></ul><p><strong>机の上に本があります</strong> 是引入“书”这一新信息；<strong>本は机の上にあります</strong> 是说明已知的书在哪里。</p><h2 id="过去时-名词谓语" tabindex="-1">过去时：名词谓语 <a class="header-anchor" href="#过去时-名词谓语" aria-label="Permalink to &quot;过去时：名词谓语&quot;">​</a></h2><p><strong>规则：</strong> 礼貌体的名词句把 です 改为 <strong>でした</strong>。否定过去时用 <strong>ではありませんでした</strong>，口语中也可说 <strong>じゃありませんでした</strong>。な形容词作谓语时也适用。</p><table tabindex="0"><thead><tr><th>含义</th><th>句型</th><th>例句</th></tr></thead><tbody><tr><td>过去肯定</td><td>A は B でした</td><td>昨日は休みでした。——昨天休息。</td></tr><tr><td>过去否定</td><td>A は B ではありませんでした</td><td>昨日は休みではありませんでした。——昨天不休息。</td></tr></tbody></table><p>普通体分别用 <strong>だった</strong> 和 <strong>ではなかった</strong>（或 <strong>じゃなかった</strong>）：昨日は休みだった。——昨天休息。</p><h2 id="过去时-动词谓语" tabindex="-1">过去时：动词谓语 <a class="header-anchor" href="#过去时-动词谓语" aria-label="Permalink to &quot;过去时：动词谓语&quot;">​</a></h2><p><strong>规则：</strong> 礼貌体动词肯定过去时由 <strong>～ます</strong> 变为 <strong>～ました</strong>；否定过去时由 <strong>～ません</strong> 变为 <strong>～ませんでした</strong>。普通体过去时取决于动词类别，不能简单地把 ます 换成 た。</p><table tabindex="0"><thead><tr><th>含义</th><th>礼貌体</th><th>普通体</th></tr></thead><tbody><tr><td>过去肯定</td><td>昨日、映画を見ました。——昨天看了电影。</td><td>昨日、映画を見た。</td></tr><tr><td>过去否定</td><td>昨日、映画を見ませんでした。——昨天没看电影。</td><td>昨日、映画を見なかった。</td></tr></tbody></table><p>例如，行きます → 行きました → 行った；食べます → 食べました → 食べた。</p><h2 id="疑问词与-が" tabindex="-1">疑问词与 が <a class="header-anchor" href="#疑问词与-が" aria-label="Permalink to &quot;疑问词与 が&quot;">​</a></h2><p><strong>规则：</strong> 询问“谁／什么是主语”时，疑问词后用 が，例如 誰が／何が。回答时通常也用 が 指明这个主语。如果把人或事物作为已知话题，或要作对比，也可能用 は；“用 が 提问就必须用 が 回答”过于绝对。</p><ul><li>誰が来ましたか。——谁来了？</li><li>田中さんが来ました。——田中来了。</li><li>何がありますか。——有什么？</li><li>机の上に本があります。——桌上有一本书。</li></ul><h2 id="この-その-あの-どの" tabindex="-1">この／その／あの／どの <a class="header-anchor" href="#この-その-あの-どの" aria-label="Permalink to &quot;この／その／あの／どの&quot;">​</a></h2><p><strong>规则：</strong> 这些词是 <strong>連体詞（连体词）</strong>，直接修饰名词，后面必须接名词：この本（这本书）、その本（你那边的／刚提到的那本书）、あの本（远处那本书）、どの本（哪本书）。不说出名词而单独指代事物时，改用 これ／それ／あれ／どれ。</p><ul><li>この本は面白いです。——这本书很有趣。</li><li>これは面白いです。——这个很有趣。</li><li>どの本があなたのですか。——哪本书是你的？</li><li>どれがあなたのですか。——哪个是你的？</li></ul>',42)])])}const b=r(l,[["render",s]]);export{u as __pageData,b as default};
